import logging
import sys
import urllib.parse
from typing import Optional, List, Dict
from taf.sw.nadcm.httpclient.ApiClient import ApiClient
from taf.sw.nadcm.httpclient.nadcm_uri import EventsStasherURI


class EeventStasherV1(object):
    def __init__(self, configuration, access_token):
        self.api_client = ApiClient(configuration, access_token)
        self._safe_chars = "(,')"

    def get_active_events(self, timeout=60):
        return self._get_all_events(filter='eq(active,true)', timeout=timeout)

    def get_active_events_for_node(self, node_ip, timeout=60):
        return self._get_all_events(filter=f"and(eq(active,true),eq(server,'{node_ip}'))", timeout=timeout)

    def _build_or_filter(self, field_name: str, values: List[str]) -> Optional[str]:
        """Construct an OR filter for a list of values."""
        if not values:
            return None
        return "or(" + ",".join(f"eq({field_name},'{value}')" for value in values) + ")" if len(values) > 1 else f"eq({field_name},'{values[0]}')"

    def _get_filter_list_for_events(self,
                                    since: Optional[int] = None,
                                    severity_list: List[str] = [],
                                    device_name_list: List[str] = [],
                                    **filter: Optional[str]) -> List[str]:
        filters_list = []

        if since:
            if not isinstance(since, int):
                raise ValueError("`since` must be an integer representing a Unix timestamp.")
            filters_list.append(f"gt(read_timestamp,{since})")
        filters_list.extend(
                f"eq({key},{value})" if value in ["true", "false"] else f"eq({key},'{value}')"
                for key, value in filter.items()
            )

        severity_filter = self._build_or_filter("severity", severity_list)
        if severity_filter:
            filters_list.append(severity_filter)
        device_name_filter = self._build_or_filter("devicename", device_name_list)
        if device_name_filter:
            filters_list.append(device_name_filter)
        return filters_list

    def get_events(self,
                   since: Optional[int] = None,
                   limit: Optional[int] = None,
                   severity_list: Optional[List[str]] = None,
                   device_name_list: Optional[List[str]] = None,
                   timeout=60,
                   **filter: Optional[str]) -> dict:
        if severity_list is None:
            severity_list = []
        if device_name_list is None:
            device_name_list = []
        filters_list = self._get_filter_list_for_events(since, severity_list, device_name_list, **filter)
        return self._get_all_events(filter=self._get_filter_string(filters_list), limit=limit, timeout=timeout)

    def _get_filter_string(self, filter_list: List[str]) -> str:
        if not filter_list:
            return ""
        if len(filter_list) == 1:
            return filter_list[0]
        return "and(" + ",".join(filter_list) + ")"

    def _add_last_id_to_filter(self, filter: str, lastid: str) -> str:
        last_id_filter = f"lt(id,'{lastid}')"
        if not filter:
            return last_id_filter
        if not filter.startswith("and("):
            return f"and({filter},{last_id_filter})"
        return filter[:-1] + f",{last_id_filter})"

    def _get_all_events(self, filter = "", limit = 0, timeout=60) -> dict:
        params = {k: v for k, v in (("filter", filter), ("limit", limit)) if v}
        events : List[Dict]= []
        max_allowed_limit = sys.maxsize  # not known yet
        while True:
            uri = f"{EventsStasherURI().events_default_uri}?{urllib.parse.urlencode(params, safe=self._safe_chars)}"
            try:
                response = self.api_client.send_get_request(uri=uri.format(skip=len(events)), timeout=timeout)
            except RuntimeError as e:
                if "reason: invalid limit, max allowed value is: " not in str(e):
                    raise
                max_allowed_limit = int(str(e).split("reason: invalid limit, max allowed value is: ")[1])
                logging.info(f"Max allowed limit is {max_allowed_limit}, reading in chunks.")
                params["limit"] = max_allowed_limit
                continue
            events.extend(response['events'])
            if limit and len(events) < limit:
                    params["limit"] = min(max_allowed_limit, limit - len(events))
            lastid = response['lastid']
            if (not lastid) or (limit and len(events) >= limit):
                break
            params["filter"] = self._add_last_id_to_filter(filter, lastid)
        return {'lastid': '', 'events': events}

    def get_events_for_node(self, node_ip, since=None, timeout=60):
        filter_list = self._get_filter_list_for_events(since, server=node_ip)
        return self._get_all_events(filter=self._get_filter_string(filter_list), timeout=timeout)

    def clear_event(self, event_id, timeout=60):
        uri = EventsStasherURI().events_default_uri + "/" + event_id
        return self.api_client.send_delete_request(uri=uri, timeout=timeout)
